/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M12 0a1 1 0 0 1 1 1v2h2a1 1 0 1 1 0 2h-2v2a1 1 0 1 1-2 0V5H9a1 1 0 0 1 0-2h2V1a1 1 0 0 1 1-1M7.792 2.406A2 2 0 0 0 9 6h1v1a2 2 0 0 0 3.594 1.208 2 2 0 0 1-.183 2.619L8.827 15.41a2 2 0 0 1-2.829 0L.586 9.998A2 2 0 0 1 0 8.584V4a2 2 0 0 1 2-2h4.584a2 2 0 0 1 1.208.406m-5.8 3.081a1.494 1.494 0 1 0 2.99 0 1.494 1.494 0 0 0-2.99 0"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M15 1a1 1 0 0 1 1 1v2h2a1 1 0 1 1 0 2h-2v2a1 1 0 1 1-2 0V6h-2a1 1 0 1 1 0-2h2V2a1 1 0 0 1 1-1m-4.19 2.393A2 2 0 0 0 12 7h1v1a2 2 0 0 0 3.607 1.19l.805.805a2 2 0 0 1 0 2.829l-4.588 4.588a2 2 0 0 1-2.829 0l-7.41-7.41A2 2 0 0 1 2 8.588V4a2 2 0 0 1 2-2h4.588a2 2 0 0 1 1.414.586zM3.993 5.489a1.495 1.495 0 1 0 2.99 0 1.495 1.495 0 0 0-2.99 0"] as readonly string[];

export const TagAddIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="tag-add" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
TagAddIcon.displayName = `Blueprint6.Icon.TagAddIcon`;

/**
 * @deprecated Use {@link TagAddIcon} instead.
 */
export const TagAdd: typeof TagAddIcon = TagAddIcon;

export default TagAddIcon;
